gawh(){return"\u064a\u0633\u062a\u0642\u0631 \u0627\u0644\u0641\u0631\u064a\u0642 \u0641\u064a \u0646\u0635\u0641 \u0645\u0644\u0639\u0628 \u0627\u0644\u062e\u0635\u0645\u060c \u0648\u064a\u0628\u0642\u0649 \u0639\u062f\u062f \u0642\u0644\u064a\u0644 \u0645\u0646 \u0627\u0644\u0644\u0627\u0639\u0628\u064a\u0646 \u0641\u064a \u0627\u0644\u062e\u0644\u0641."},
gawo(){return"\u0644\u0627 \u064a\u0628\u062f\u0623 \u0627\u0644\u0636\u063a\u0637 \u0625\u0644\u0627 \u062d\u064a\u0646 \u064a\u0642\u062a\u0631\u0628 \u0627\u0644\u062e\u0635\u0645 \u0645\u0646 \u0645\u0646\u0637\u0642\u0629 \u062c\u0632\u0627\u0626\u0643. \u0644\u0627 \u0623\u062d\u062f \u064a\u0644\u0627\u062d\u0642 \u0627\u0644\u0643\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0645\u0627\u0645."},
gawp(){return"\u064a\u0628\u062f\u0623 \u0627\u0644\u0636\u063a\u0637 \u062d\u064a\u0646 \u064a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062e\u0635\u0645 \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628. \u0644\u0627 \u0645\u0633\u0627\u062d\u0629 \u062d\u0631\u0629 \u0623\u0645\u0627\u0645\u0643."},
gawn(){return"\u064a\u064f\u0644\u0627\u062d\u064e\u0642 \u0627\u0644\u062e\u0635\u0645 \u0645\u0646\u0630 \u062d\u0627\u0631\u0633\u0647. \u0648\u0639\u0646\u062f \u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0643\u0631\u0629 \u064a\u064f\u062d\u0627\u0648\u064e\u0644 \u0627\u0633\u062a\u0631\u062c\u0627\u0639\u0647\u0627 \u0641\u0648\u0631\u064b\u0627."},
gawl(){return"\u062a\u064f\u0646\u0642\u0644 \u0627\u0644\u0643\u0631\u0629 \u0639\u0628\u0631 \u0623\u0642\u0631\u0628 \u0644\u0627\u0639\u0628\u060c \u0648\u0644\u0627 \u062a\u064f\u062c\u0631\u064e\u0651\u0628 \u0627\u0644\u0643\u0631\u0627\u062a \u0627\u0644\u0637\u0648\u064a\u0644\u0629."},
gawm(){return"\u062a\u064f\u0646\u0642\u0644 \u0627\u0644\u0643\u0631\u0629 \u0628\u062a\u0645\u0631\u064a\u0631\u0627\u062a \u0642\u0635\u064a\u0631\u0629. \u0648\u0644\u0627 \u062a\u0623\u062a\u064a \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0637\u0648\u064a\u0644\u0629 \u0625\u0644\u0627 \u062d\u064a\u0646 \u062a\u0646\u0639\u062f\u0645 \u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0623\u062e\u0631\u0649."},
gawk(){return"\u062a\u064f\u0631\u0633\u0644 \u0627\u0644\u0643\u0631\u0629 \u0633\u0631\u064a\u0639\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u062f\u0648\u0646 \u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0645\u0631\u064a\u0631\u0629 \u0628\u064a\u0646\u064a\u0629."},
gawc(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0623\u0645\u0627\u0645 \u0645\u0646\u0637\u0642\u0629 \u062c\u0632\u0627\u0626\u0647. \u0644\u0627 \u062a\u0628\u0642\u0649 \u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647."},
gawd(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062a\u064f\u062a\u0631\u0643 \u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u064a \u0623\u0645\u0627\u0645\u0647 \u0644\u0644\u062e\u0635\u0645."},
gawe(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0646\u0635\u0641 \u0645\u0644\u0639\u0628\u0647\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0627\u0644\u062d\u0627\u0631\u0633 \u0645\u063a\u0644\u0642\u0629."},
gawf(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0648\u0627\u0633\u0639\u0629."},
