gawq(){return"\u064a\u062a\u062c\u0645\u0639 \u0627\u0644\u062c\u0645\u064a\u0639 \u0641\u064a \u0627\u0644\u0639\u0645\u0642\u060c \u0648\u062a\u0628\u0642\u0649 \u0627\u0644\u0623\u062c\u0646\u062d\u0629 \u0641\u0627\u0631\u063a\u0629."},
