gasG(){return"\u0646\u0627\u0642\u0635\u0629"},
gasA(){return"\u0627\u0644\u0644\u064a\u0627\u0642\u0629 \xb7 \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629"},
asH(a,b){return""+a+" "+b},
gasC(){return"\u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u0627\u0644\u0623\u062d\u062f \u0639\u0634\u0631 \u0641\u064a \u0643\u0627\u0645\u0644 \u0646\u0634\u0627\u0637\u0647\u0645: \u064a\u0628\u062f\u0623 \u0627\u0644\u062c\u0645\u064a\u0639 \u0628\u0643\u0627\u0645\u0644 \u0642\u0648\u062a\u0647\u0645."},
gasF(){return"\u0627\u0644\u0645\u062a\u0639\u0628\u0648\u0646 \u064a\u0644\u0639\u0628\u0648\u0646 \u062f\u0648\u0646 \u0645\u0633\u062a\u0648\u0627\u0647\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0647\u0645 \u0623\u0643\u062b\u0631 \u0639\u0631\u0636\u0629 \u0644\u0644\u0625\u0635\u0627\u0628\u0629."},
gasD(){return"\u0627\u0644\u0645\u0646\u0647\u0643\u0648\u0646 \u064a\u0644\u0639\u0628\u0648\u0646 \u062f\u0648\u0646 \u0645\u0633\u062a\u0648\u0627\u0647\u0645 \u0628\u0648\u0636\u0648\u062d \u0648\u0647\u0645 \u0634\u062f\u064a\u062f\u0648 \u0627\u0644\u0639\u0631\u0636\u0629 \u0644\u0644\u0625\u0635\u0627\u0628\u0629."},
