gask(){return"\u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u064a\u0639\u0631\u0641\u0648\u0646 \u0623\u062f\u0648\u0627\u0631 \u0628\u0639\u0636\u0647\u0645\u061b \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u0644\u0639\u0628 \u0641\u0648\u0642 \u0645\u0633\u062a\u0648\u0627\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u0634\u0643\u064a\u0644."},
gasl(){return"\u0627\u0644\u062e\u0637\u0648\u0637 \u0641\u064a \u0645\u0643\u0627\u0646\u0647\u0627\u061b \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u0644\u0639\u0628 \u0628\u0645\u0633\u062a\u0648\u0627\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u0634\u0643\u064a\u0644."},
gasn(){return"\u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u062a\u062a\u0633\u0639 \u0648\u0627\u0644\u0636\u063a\u0637 \u064a\u062a\u0623\u062e\u0631\u061b \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u0644\u0639\u0628 \u062f\u0648\u0646 \u0645\u0633\u062a\u0648\u0627\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u0634\u0643\u064a\u0644."},
gasm(){return"\u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u064a\u0628\u062d\u062b\u0648\u0646 \u0639\u0646 \u0645\u0631\u0627\u0643\u0632\u0647\u0645\u061b \u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u0641\u0642\u062f \u062c\u0632\u0621\u064b\u0627 \u0648\u0627\u0636\u062d\u064b\u0627 \u0645\u0646 \u0642\u0648\u062a\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u0634\u0643\u064a\u0644."},
gasq(){return"\u0622\u062e\u0631 5 \u0645\u0628\u0627\u0631\u064a\u0627\u062a \xb7 \u0622\u062e\u0631 5 \u062d\u0635\u0635 \u062a\u062f\u0631\u064a\u0628"},
gasp(){return"\u0627\u0644\u0645\u0628\u0627\u0631\u064a\u0627\u062a"},
gasi(){return"\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062a\u0634\u0643\u064a\u0644"},
