gas6(){return"\u062e\u0637\u0651\u0637 \u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062a\u0634\u0643\u064a\u0644"},
gasQ(){return"\u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \xb7 \u0627\u0644\u062a\u0646\u0627\u063a\u0645"},
gas8(){return"\u0627\u0644\u062c\u0645\u064a\u0639 \u0641\u064a \u0645\u0643\u0627\u0646\u0647"},
