gazU(){return"\u0623\u0633\u0628\u0648\u0639 \u062c\u062f\u064a\u062f \u0641\u064a \u0627\u0644\u062f\u0648\u0631\u064a\u060c \u0648\u0645\u0639\u0631\u0643\u0629 \u062c\u062f\u064a\u062f\u0629."},
gazQ(){return"\u0627\u0644\u0623\u0646\u0641\u0627\u0633 \u0645\u062d\u0628\u0648\u0633\u0629 \u0641\u064a \u0627\u0644\u0643\u0623\u0633\u060c \u0648\u0627\u0644\u062e\u0627\u0633\u0631 \u064a\u0646\u062a\u0647\u064a \u0645\u0634\u0648\u0627\u0631\u0647 \u0647\u0646\u0627."},
gazR(){return"\u062d\u0645\u0627\u0633 \u0627\u0644\u0643\u0623\u0633! \u0627\u0644\u0641\u0627\u0626\u0632 \u0627\u0644\u0644\u064a\u0644\u0629 \u064a\u062a\u0623\u0647\u0644."},
gazV(){return"\u0623\u0648\u0644 \u0645\u0628\u0627\u0631\u0627\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0633\u0645! \u0627\u0644\u062c\u0645\u064a\u0639 \u064a\u0631\u064a\u062f \u0628\u062f\u0627\u064a\u0629 \u062c\u064a\u062f\u0629."},
