gazL(){return"\u0643\u0627\u0644\u0639\u0627\u062f\u0629\u060c \u0645\u0639\u064a \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0643\u0645\u0627\u0644. \u0623\u0647\u0644\u0627\u064b \u0628\u0643 \u064a\u0627 \u0623\u0633\u062a\u0627\u0630!"},
gazM(){return"\u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0643\u0645\u0627\u0644 \u0645\u0639\u0646\u0627 \u0627\u0644\u0644\u064a\u0644\u0629 \u0623\u064a\u0636\u0627\u064b \u0628\u062a\u062d\u0644\u064a\u0644\u0627\u062a\u0647. \u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u064a\u0627 \u0623\u0633\u062a\u0627\u0630!"},
